/**
 * European Portuguese (pt-PT) message catalog — the third UI language.
 * Full frontend coverage completed 27 Oct 2026 (every key in `en.ts`
 * has a real Portuguese translation here — base-engine chrome, every
 * VigiCloud/QualCloud/RegCloud screen, every modal, every error code).
 * Typed as `Record<MessageKey, string>`, matching `fr.ts` exactly —
 * a missing key is now a compile error, the same safety net French
 * has always had. The backend `email-messages.ts`/
 * `notification-messages.ts` Portuguese catalogs are the one
 * remaining piece (outbound emails/notifications) — tracked in
 * todo-i18n.md, not here.
 *
 * Variant: **European Portuguese**, not Brazilian — matches
 * SafeMeds' actual pan-African Lusophone markets (Mozambique, Angola,
 * Guinea-Bissau, Cape Verde, São Tomé and Príncipe), confirmed with
 * the user rather than assumed.
 */
