  'pvCaseDetail.infoCausalityWhatThisIs': 'O que é isto:',
  'pvCaseDetail.infoCausalityBody1': 'para cada produto suspeito associado a cada reação reportada, alguém tem de julgar',
  'pvCaseDetail.infoCausalityBodyEm': 'quão provável é que este medicamento específico causou esta reação específica',
  'pvCaseDetail.infoCausalityBody2':
    '— não apenas por caso, mas por par, porque um caso com 2 medicamentos e 2 reações precisa de 4 juízos separados (o Medicamento A pode explicar claramente a erupção cutânea enquanto não tem relação com a náusea, por exemplo). Dois métodos reais de pontuação de farmacovigilância produzem esse juízo, captados de forma independente:',
  'pvCaseDetail.whoUmcLabel': 'OMS-UMC',
  'pvCaseDetail.infoCausalityWhoUmc':
    '(escolha uma de 6 categorias — Certa, Provável, Possível, Improvável, etc. — guiada por uma lista de verificação do que tem de ser verdade para cada uma)',
  'pvCaseDetail.andWord': 'e',
  'pvCaseDetail.naranjoLabel': 'Naranjo',
  'pvCaseDetail.infoCausalityNaranjo':
    '(10 perguntas sim/não/não sei, totalizadas automaticamente numa pontuação de aproximadamente -4 a +13, interpretada como Definitiva/Provável/Possível/Dúbia). Clique num par abaixo para abrir a sua avaliação.',
  'pvCaseDetail.sectionConsent': 'Consentimento',
  'pvCaseDetail.infoConsentWhatThisMeans': 'O que isto significa aqui:',
  'pvCaseDetail.infoConsentBody1': 'não consentimento para o tratamento — consentimento para',
  'pvCaseDetail.infoConsentBodyEm': 'processar e reportar',
  'pvCaseDetail.infoConsentBody2':
    'esta informação de evento adverso, incluindo partilhá-la com o regulador (PPB) se necessário. Um relato de caso contém frequentemente informação de saúde identificável, por isso, antes de ser usado e reenviado, deve haver um registo de se o paciente (ou quem reportou em seu nome) foi perguntado e concordou. Este é um registo de conformidade/auditoria, não um requisito clínico — o caso continua a existir e a poder ser processado de qualquer forma; isto apenas rastreia se a permissão foi pedida e qual foi a resposta.',
  'pvCaseDetail.reportConsentLabel': 'Consentimento do relato',
  'pvCaseDetail.sectionCaseFollowUp': 'Acompanhamento do Caso',
  'pvCaseDetail.subtitleCaseFollowUp':
    'Voltar a contactar o notificador para detalhes em falta ou uma atualização do resultado — até duas tentativas, encerrando dentro de 28 dias',
  'pvCaseDetail.infoFollowUp':
    'O acompanhamento precisa do consentimento do notificador para ser contactado (um consentimento de "contacto" separado do consentimento do relato acima) antes de um email automático ser enviado — sem ele, o sistema abre a mesma janela de tentativa rastreada mas depende de uma pessoa ligar ao notificador e registar o que aconteceu. A tentativa 1 tem 5 dias úteis para obter resposta; sem resposta escala para a tentativa 2 nos mesmos termos; ainda nada encerra o caso como falha de acompanhamento. Qualquer resposta real reinicia o relógio para 7 dias novos. O ciclo completo encerra dentro de 28 dias desde o início, independentemente de tudo.',
  'pvCaseDetail.sectionSourceDocuments': 'Documentos-Fonte',
