  // Recall Detail (RegCloud Stage 14 / QualCloud Stage 10 lifecycle)
  'recallDetail.nextStepDraft': 'Seguinte: mova esta retirada para Em avaliação. Depois construa o âmbito de produto e lote e congele-o, porque a aprovação precisa de um âmbito congelado.',
  'recallDetail.nextStepUnderAssessment': 'Seguinte: termine o âmbito de produto e lote e congele-o, adicione os países, e complete a avaliação de risco. A aprovação está bloqueada até que existam tanto um âmbito congelado como uma avaliação de risco.',
  'recallDetail.nextStepApproved': 'Seguinte: notifique as partes interessadas. Envie as suas ligações de portal e mensagens para que possam confirmar a receção e contar o stock.',
  'recallDetail.nextStepNotification': 'Seguinte: registe cada entrega e contagem de stock das partes interessadas, para que a retirada possa ser realizada (execução).',
  'recallDetail.nextStepExecution': 'Seguinte: reconcilie o stock. Mostre o que é recuperado, colocado em quarentena, destruído e ainda pendente, depois avance para reconciliação.',
