  // Quality Waste Disposal (QualCloud Phase 1 Pass B, item B)
  'wasteDisposal.step2Title': 'Submeter candidatura à PPB e pagar a taxa',
  'wasteDisposal.step2Why': 'Submeta a candidatura ao Conselho de Farmácia e Venenos no formulário da Segunda Tabela Parte A e pague a taxa de candidatura de KES 2.500 (Segunda Tabela Parte B; r.17(2)). A PPB deve emitir o Certificado de Descarte Seguro dentro de 30 dias da candidatura (r.17(3)).',
  'wasteDisposal.step3Title': 'Anexar fatura e prova de pagamento',
  'wasteDisposal.step3Why': 'Mantenha a fatura da taxa e o recibo de pagamento no processo. Ambos são obrigatórios antes que o processo possa ser encerrado.',
  'wasteDisposal.step4Title': 'Entregar a uma empresa de descarte autorizada',
  'wasteDisposal.step4Why': 'O resíduo só pode ir para uma pessoa licenciada para o descartar numa instalação aprovada (r.11(3)). Registe a empresa, anexe o seu certificado, e marque o certificado como verificado pela PPB.',
  'wasteDisposal.step5Title': 'Destruição sob supervisão',
  'wasteDisposal.step5Why': 'O descarte é supervisionado pelo Conselho num local aprovado pelo NEMA (r.17(1)). O processo do cliente também requer a presença de um representante do cliente e de um oficial da PPB. Carregue as fotografias da destruição; são combinadas num único PDF.',
  'wasteDisposal.step6Title': 'Anexar o Certificado de Descarte Seguro da PPB',
